      if (el.closest(".mlh-root, [data-component='HomeBrowserHub.TabList']")) continue;
      const label = (el.textContent || el.getAttribute("aria-label") || "").replace(/\s+/g, " ").trim();
      if (!label || seen.has(label)) continue;
